from __future__ import annotations
import base64
import gzip
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
PAYLOADS = {
    "apps/web/workbench-ui.js": "[... huge base64 omitted for brevity?]",
    "apps/web/workbench.css": "H4sIALmohmoC/7U9247jOnLv8xXKGWwwfdb2SNTdBhZJFti8bJBgz0PySkm0rbRsOZI83b2G/z28izfJcs/ZaWDQLfFSLBbrXtS2a9vh9sXz1uu3Yl0ctl8DPwBBtBOPOlg3269+4Vc+kg/P8AduiJsFiXzWX7s9LBF+ngR5UJjP1wC/KQIEAutNuP0KfBCBTL5p6jMe...",
    "apps/web/index.html": ""
}
for rel, data in PAYLOADS.items():
    path = ROOT / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(gzip.decompress(base64.b64decode(data)))

replacements = {
    "pyproject.toml": [('version = "0.13.9"', 'version = "0.14.0"')],
    "packaging/windows/MailAgent.iss": [('#define MyAppVersion "0.13.9"', '#define MyAppVersion "0.14.0"')],
    "packages/agent_core/mail_agent_core/identity.py": [('app_version: str = "0.13.9"', 'app_version: str = "0.14.0"')],
    "apps/web/desktop-links.js": [("const APP_VERSION = '0.13.9'", "const APP_VERSION = '0.14.0'")],
    "apps/gateway/mail_agent_gateway/main.py": [('APP_VERSION = "0.13.9"', 'APP_VERSION = "0.14.0"')],
    "apps/launcher/mail_agent_launcher/main.py": [('APP_VERSION = "0.13.9"', 'APP_VERSION = "0.14.0"')],
}
for rel, repls in replacements.items():
    path = ROOT / rel
    text = path.read_text(encoding="utf-8")
    for old, new in repls:
        if old not in text:
            raise SystemExit(f"missing expected marker in {rel}: {old}")
        text = text.replace(old, new)
    path.write_text(text, encoding="utf-8")

for rel in [
    "tests/test_recovery_contract.py",
    "tests/test_startup_nonblocking.py",
    "tests/test_attention_ui_contract.py",
    "tests/test_windows_update_restart.py",
]:
    path = ROOT / rel
    text = path.read_text(encoding="utf-8").replace("0.13.9", "0.14.0")
    path.write_text(text, encoding="utf-8")

att = ROOT / "tests/test_attention_ui_contract.py"
text = att.read_text(encoding="utf-8")
text = text.replace('js = (ROOT / "apps/web/attention-center.js").read_text(encoding="utf-8")', 'js = (ROOT / "apps/web/workbench-ui.js").read_text(encoding="utf-8")')
text = text.replace('assert "/assets/attention-center.js?v=0.14.0" in index', 'assert "/assets/workbench-ui.js?v=0.14.0" in index\n    assert "/assets/attention-center.js?v=0.14.0" not in index')
text = text.replace('assert ".observe(app, {childList:true})" in js\n    assert "subtree:true" not in js.replace(" ", "")', 'assert "MutationObserver" not in js')
text = text.replace('str(ROOT / "apps/web/attention-center.js")', 'str(ROOT / "apps/web/workbench-ui.js")')
att.write_text(text, encoding="utf-8")

startup = ROOT / "tests/test_startup_nonblocking.py"
text = startup.read_text(encoding="utf-8")
text = text.replace('"desktop-links.js",', '"desktop-links.js",\n        "workbench.css",\n        "workbench-ui.js",')
startup.write_text(text, encoding="utf-8")

(ROOT / "tests/test_workbench_ui.py").write_text('from __future__ import annotations\n\nimport shutil\nimport subprocess\nfrom pathlib import Path\n\nimport pytest\n\nROOT = Path(__file__).resolve().parents[1]\n\n\ndef test_workbench_is_first_class_and_legacy_attention_enhancer_is_not_loaded():\n    index = (ROOT / "apps/web/index.html").read_text(encoding="utf-8")\n    assert "/assets/workbench.css?v=0.14.0" in index\n    assert "/assets/workbench-ui.js?v=0.14.0" in index\n    assert "/assets/dashboard-live.js?v=0.14.0" in index\n    assert "/assets/attention-center.js" not in index\n\n\ndef test_workbench_preserves_core_actions_and_settings():\n    source = (ROOT / "apps/web/workbench-ui.js").read_text(encoding="utf-8")\n    for marker in (\n        "runAgentNow",\n        "syncNow",\n        "data-approve",\n        "data-reject",\n        "data-draft-edit",\n        "data-draft-submit",\n        "/v1/attention?limit=200",\n        "/v1/attention/resolve",\n        "/v1/settings/behavior",\n        "mark_processed_read",\n        "newsletter_action",\n        "advertising_action",\n        "saveBehaviorSettings",\n        "saveBrainSettings",\n        "probeSettingsProvider",\n        "check-update",\n        "install-update",\n    ):\n        assert marker in source\n\n\ndef test_workbench_has_real_filters_and_command_palette_not_placeholder_controls():\n    source = (ROOT / "apps/web/workbench-ui.js").read_text(encoding="utf-8")\n    assert "data-inbox-filter" in source\n    assert "data-attention-filter" in source\n    assert "function openCommand()" in source\n    assert \'data-command-action="sync"\' in source\n    assert \'data-command-action="run"\' in source\n    assert "design-preview" not in source\n    assert "installDemoData" not in source\n\n\ndef test_workbench_javascript_syntax():\n    node = shutil.which("node")\n    if not node:\n        pytest.skip("Node.js is not available")\n    result = subprocess.run(\n        [node, "--check", str(ROOT / "apps/web/workbench-ui.js")],\n        capture_output=True,\n        text=True,\n        check=False,\n    )\n    assert result.returncode == 0, result.stderr\n', encoding="utf-8")

for path in [ROOT / "apps/web/workbench-ui.js", ROOT / "apps/web/workbench.css", ROOT / "apps/web/index.html", ROOT / "tests/test_workbench_ui.py"]:
    text = path.read_text(encoding="utf-8")
    path.write_text("\n".join(line.rstrip() for line in text.splitlines()) + "\n", encoding="utf-8")
